CREATE TABLE inventory_fulfillment (id BIGINT PRIMARY KEY,fulfillment_no VARCHAR(64) NOT NULL,order_no VARCHAR(64) NOT NULL,user_id BIGINT NOT NULL,merchant_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP(3) NOT NULL,updated_at TIMESTAMP(3) NOT NULL,UNIQUE KEY uk_fulfillment_no(fulfillment_no),UNIQUE KEY uk_fulfillment_order_warehouse(order_no,warehouse_id),KEY idx_fulfillment_merchant(merchant_id,status));
CREATE TABLE inventory_fulfillment_item (id BIGINT PRIMARY KEY,fulfillment_id BIGINT NOT NULL,order_item_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,quantity INT NOT NULL,shipped_qty INT NOT NULL DEFAULT 0,UNIQUE KEY uk_fulfillment_item(fulfillment_id,order_item_id));
CREATE TABLE inventory_package (id BIGINT PRIMARY KEY,package_no VARCHAR(64) NOT NULL,fulfillment_id BIGINT NOT NULL,carrier_code VARCHAR(32) NOT NULL,tracking_no VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,shipped_at TIMESTAMP(3) NULL,received_at TIMESTAMP(3) NULL,created_at TIMESTAMP(3) NOT NULL,UNIQUE KEY uk_package_no(package_no),UNIQUE KEY uk_tracking(carrier_code,tracking_no));
CREATE TABLE inventory_logistics_track (id BIGINT PRIMARY KEY,package_id BIGINT NOT NULL,node_code VARCHAR(32) NOT NULL,detail VARCHAR(500) NOT NULL,occurred_at TIMESTAMP(3) NOT NULL,created_at TIMESTAMP(3) NOT NULL,KEY idx_track_package(package_id,occurred_at));
